// Local compatibility adapter; output follows openvela's official schema.
import { spawn } from 'node:child_process';
import { readFileSync, existsSync, realpathSync, writeFileSync, mkdirSync } from 'node:fs';
import { relative } from 'node:path';
import { fileURLToPath } from 'node:url';
const config = JSON.parse(readFileSync(new URL('./config.json', import.meta.url), 'utf8'));
const script = fileURLToPath(new URL('./collector.py', import.meta.url));
export default {
  id: 'openvela-contest-compat',
  server({client, directory, worktree}) {
    const cwd=realpathSync(directory || worktree || process.cwd());
    const rel=relative(config.workspace,cwd);
    if(rel==='..' || rel.startsWith('../') || rel.startsWith('/') || !existsSync(config.workspace+'/.repo'))return {};
    mkdirSync(config.state,{recursive:true});
    writeFileSync(config.state+'/opencode-loaded.json',JSON.stringify({at:new Date().toISOString(),cwd}));
    let queue=Promise.resolve();
    async function capture(id) {
      const response=await client.session.messages({path:{id}});
      if(response.error)throw new Error('session.messages failed: '+JSON.stringify(response.error));
      const messages=response.data ?? response;
      if(!Array.isArray(messages))throw new Error('Unexpected session.messages format');
      const meta=await client.session.get({path:{id}});
      const data={cwd,session_id:id,messages,started_at:(meta.data ?? meta)?.time?.created};
      await new Promise((ok,fail)=>{
        const child=spawn(config.python,[script,'--tool','opencode'],{stdio:['pipe','ignore','pipe']});
        let stderr='';const timer=setTimeout(()=>{child.kill();fail(new Error('collector timeout'))},30000);
        child.stderr.on('data',b=>{stderr+=b});
        child.on('error',e=>{clearTimeout(timer);fail(e)});
        child.on('close',code=>{clearTimeout(timer);code===0?ok():fail(new Error(stderr))});
        child.stdin.on('error',fail);child.stdin.end(JSON.stringify(data));
      });
    }
    return {
      event:async({event})=>{
        if(event.type!=='session.idle')return;
        const id=event.properties?.sessionID || event.properties?.sessionId;
        if(!id)return;
        queue=queue.then(()=>capture(id)).catch(e=>{
          writeFileSync(config.state+'/opencode-error.json',JSON.stringify({at:new Date().toISOString(),error:e.message}));
          console.error('[session-log]',e.message);
        });
        await queue;
      },
      dispose:async()=>{await queue}
    };
  }
};

